{
  "PROP-57888860-inv-029": {
    "property_id": "PROP-57888860-inv-029",
    "audit_result": {
      "property_id": "PROP-57888860-inv-029",
      "classification": "vulnerability",
      "code_path": "beacon_chain/spec/peerdas_helpers.nim::get_data_column_sidecars::L275-276",
      "proof_trace": "Code adds entire cells/proofs arrays instead of selecting column-specific elements: uses cellsAndProofs[i].cells instead of cellsAndProofs[i].cells[column_index], causing each sidecar.column to contain NUMBER_OF_COLUMNS * blob_count cells instead of blob_count cells, violating len(sidecar.column) == len(kzg_commitments).",
      "attack_scenario": "Malicious block proposer or validator provides crafted CellsAndProofs that exploit the missing column index, causing data column sidecars with incorrect cell counts that fail validation at gossip recipients, leading to network-wide block propagation failure or consensus disruption.",
      "checklist_id": "PROP-57888860-inv-029"
    },
    "text": "Each sidecar must contain exactly one cell and one proof per blob in the block.",
    "assertion": "forall sidecar in sidecars: len(sidecar.column) == len(kzg_commitments) AND len(sidecar.kzg_proofs) == len(kzg_commitments)",
    "covers": "SG-003",
    "severity": "MEDIUM",
    "type": "invariant"
  }
}

for blbIdx, blob in blobs.pairs:
  let cellsAndProofs = computeCellsAndKzgProofs(blob)
  if cellsAndProofs.isErr:
    return err("Computing Extended Matrix: Issue computing cells and proofs")

  for i in 0..<fulu.CELLS_PER_EXT_BLOB:
    extended_matrix.add(MatrixEntry(
      cell: cellsAndProofs.get.cells[i],
      kzg_proof: cellsAndProofs.get.proofs[i],
      row_index: blbIdx.uint64,
      column_index: i.uint64
    ))

ok(extended_matrix)

# https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.3/specs/fulu/p2p-interface.md#verify_data_column_sidecar_kzg_proofs
proc verify_data_column_sidecar_kzg_proofs*(sidecar: fulu.DataColumnSidecar):
                                            Result[void, cstring] =
  ## Verify if the KZG proofs are correct.

  # Iterate through the cell indices
  var cellIndices = newSeqOfCap[CellIndex](sidecar.column.len)
  for _ in 0..<sidecar.column.len:
    cellIndices.add(CellIndex(sidecar.index))

  let res = verifyCellKzgProofBatch(
      sidecar.kzg_commitments.asSeq, cellIndices, sidecar.column.asSeq,
      sidecar.kzg_proofs.asSeq).valueOr:
    return err("DataColumnSidecar: validation error")

  if not res:
    return err("DataColumnSidecar: validation failed")

  ok()

  when typeof(blck).kind in [ConsensusFork.Deneb, ConsensusFork.Electra]:
    if blobsOpt.isSome:
      let blobs = blobsOpt.get()
      let kzgCommits = blck.message.body.blob_kzg_commitments.asSeq
      if blobs.len > 0 or kzgCommits.len > 0:
        let res = validate_blobs(
          kzgCommits,
          blobs.mapIt(KzgBlob(bytes: it.blob)),
          blobs.mapIt(it.kzg_proof))
        if res.isErr():
          warn "blobs failed validation",
            blockRoot = shortLog(blck.root),
            blobs = shortLog(blobs),
            blck = shortLog(blck.message),
            signature = shortLog(blck.signature),
            msg = res.error()
          return err(res.error())

let
  sendTime = router[].getCurrentBeaconTime()
  delay = sendTime - blck.message.slot.block_deadline()
  # The block (and blobs, if present) passed basic gossip validation
  # - we can "safely" broadcast it now. In fact, per the spec, we
  # should broadcast it even if it later fails to apply to our
  # state.

let res = await router[].network.broadcastBeaconBlock(blck)

if res.isOk():
  beacon_blocks_sent.inc()
  beacon_blocks_sent_delay.observe(delay.toFloatSeconds())

  notice "Block sent",
    blockRoot = shortLog(blck.root), blck = shortLog(blck.message),
    signature = shortLog(blck.signature), delay
else: # "no broadcast" is not a fatal error
  notice "Block not sent",
    blockRoot = shortLog(blck.root), blck = shortLog(blck.message),
    signature = shortLog(blck.signature), error = res.error()

when typeof(blck).kind >= ConsensusFork.Fulu:
  var dataColumnRefs = Opt.none(fulu.DataColumnSidecars)
  let dataColumns = dataColumnsOpt.get()
  if dataColumnsOpt.isSome() and dataColumns.len != 0:
    var das_workers =
      newSeq[Future[SendResult]](len(dataColumns))
    for i in 0..<dataColumns.lenu64:
      let subnet_id =
        compute_subnet_for_data_column_sidecar(dataColumns[i].index)

when typeof(blck).kind >= ConsensusFork.Fulu:
  var dataColumnRefs = Opt.none(fulu.DataColumnSidecars)
  let dataColumns = dataColumnsOpt.get()
  if dataColumnsOpt.isSome() and dataColumns.len != 0:
    var das_workers =
      newSeq[Future[SendResult]](len(dataColumns))
    for i in 0..<dataColumns.lenu64:
      let subnet_id =
        compute_subnet_for_data_column_sidecar(dataColumns[i].index)

      das_workers[i] =
        router[].network.broadcastDataColumnSidecar(subnet_id,
                                                    dataColumns[i])
    let allres = await allFinished(das_workers)
    for i in 0..<allres.len:
      let res = allres[i]
      doAssert res.finished()
      if res.failed():
        notice "Data column not sent",
          data_column = shortLog(dataColumns[i]), error = res.error[]
      else:
        notice "Data column sent",
          data_column = shortLog(dataColumns[i])
    # Push only those columns to processor for which we custody
    let
      metadata = router[].network.metadata.custody_group_count
      samples_per_slot = router[].network.cfg.SAMPLES_PER_SLOT
      custody_columns =
        router[].network.cfg.resolve_columns_from_custody_groups(
          router[].network.nodeId,
          max(samples_per_slot, metadata))

    var final_columns: seq[ref fulu.DataColumnSidecar]
    for dc in dataColumns:
      if dc.index in custody_columns:
        final_columns.add newClone(dc)
    dataColumnRefs = Opt.some(final_columns)
  let added = await router[].blockProcessor[].addBlock(
    MsgSource.api, ForkedSignedBeaconBlock.init(blck), dataColumnRefs)
elif typeof(blck).kind in [ConsensusFork.Deneb, ConsensusFork.Electra]:

